// lib/game_content_localization.dart
// Traduction (22 langues) des noms de rôles du Loup-Garou, des catégories par défaut
// et des consignes du Cadavre Exquis, dont les valeurs de référence restent en français
// (clés stockées dans Firestore / utilisées par la logique de jeu).
// Ordre des langues : fr, en, es, de, it, pt, nl, pl, ru, uk, ro, el, cs, sv, da, fi, no, hu, sk, hr, bg, tr.

import 'package:flutter/widgets.dart';

class GameContentLocalization {
  static const List<String> _langs = [
    'fr', 'en', 'es', 'de', 'it', 'pt', 'nl', 'pl', 'ru', 'uk', 'ro',
    'el', 'cs', 'sv', 'da', 'fi', 'no', 'hu', 'sk', 'hr', 'bg', 'tr',
  ];

  static String _code(BuildContext? context) {
    if (context == null) return 'fr';
    try {
      return Localizations.localeOf(context).languageCode.toLowerCase();
    } catch (_) {
      return 'fr';
    }
  }

  static String? _lookup(Map<String, String> table, String lang, String fr) {
    final row = table[fr];
    if (row == null) return null;
    final idx = _langs.indexOf(lang);
    final parts = row.split('|');
    if (idx < 0 || idx >= parts.length) return parts.length > 1 ? parts[1] : fr;
    return parts[idx];
  }

  /// Nom de rôle traduit (renvoie null si le rôle est inconnu).
  static String? roleName(String lang, String roleFr) => _lookup(_roles, lang, roleFr);

  /// Catégorie par défaut traduite (renvoie le texte d'origine si inconnue).
  static String category(BuildContext? context, String categoryFr) =>
      _lookup(_categories, _code(context), categoryFr) ?? categoryFr;

  /// Consigne du Cadavre Exquis traduite (renvoie le texte d'origine si inconnue).
  static String cadavrePrompt(BuildContext? context, String promptFr) =>
      _lookup(_cadavre, _code(context), promptFr) ?? promptFr;

  /// Consigne « Écrivez {élément} » du Cadavre Exquis ; l'élément est traduit s'il est connu.
  static String writePrompt(BuildContext? context, String promptItemFr) {
    final lang = _code(context);
    final item = _lookup(_cadavre, lang, promptItemFr) ?? promptItemFr;
    final tpl = _lookup(_cadavre, lang, 'Écrivez {0}') ?? 'Écrivez {0}';
    return tpl.replaceAll('{0}', item);
  }

  /// Consigne « Complétez la phrase (1 à 8 mots) » traduite.
  static String completeSentence(BuildContext? context) =>
      _lookup(_cadavre, _code(context), 'Complétez la phrase (1 à 8 mots)') ??
      'Complétez la phrase (1 à 8 mots)';

  /// Texte d'interface (écrans d'accueil / création de partie) traduit ; renvoie le français si inconnu.
    /// Formate un texte avec arguments {0}, {1}...
  static String format(BuildContext? context, String tplFr, List<dynamic> args) {
    var text = ui(context, tplFr);
    for (int i = 0; i < args.length; i++) {
      text = text.replaceAll('{$i}', args[i].toString());
    }
    return text;
  }

  static String ui(BuildContext? context, String frText) =>
      _lookup(_ui, _code(context), frText) ?? _lookup(_roles, _code(context), frText) ?? frText;

